 function settingsPage(){const tabs=['פרטי העסק','מיתוג','עובדים','תפקידים','הרשאות','אזורי חלוקה','נהגים','מוצרים','מחירונים','מלאי מינימום','מבצעים','יעדים','ספקים','התראות'];const active=tab||tabs[0];return <><Tabs items={tabs} value={active} onChange={setTab}/><Card title={active}>{active==='פרטי העסק'?<div className="form-grid"><Field label="שם העסק"><input value={D.tenant.name} readOnly/></Field><Field label="טלפון"><input value={settings.phone||D.tenant.phone} onChange={e=>setSettings(s=>({...s,phone:e.target.value}))}/></Field><Field label="כתובת"><input value={settings.address||D.tenant.address} onChange={e=>setSettings(s=>({...s,address:e.target.value}))}/></Field></div>:active==='מיתוג'?<div className="form-grid"><Field label="צבע מותג"><input type="color" value={settings.color||'#24897b'} onChange={e=>setSettings(s=>({...s,color:e.target.value}))}/></Field><Field label="כותרת מערכת"><input value={settings.title||'מערכת ניהול ותפעול'} onChange={e=>setSettings(s=>({...s,title:e.target.value}))}/></Field></div>:active==='מבצעים'?<><Table headers={['שם','מוצר','קהל','הנחה','התחלה','סיום','מצב']} rows={[[settings.promo||'הנחת ספטמבר – בלון 48 ק״ג','בלון 48 ק״ג','לקוחות פרטיים','5%','01/09/2026','30/09/2026',<Badge>{settings.promoDisabled?'מושבת':'פעיל'}</Badge>]]}/><Button onClick={()=>{setSettings(s=>({...s,promoDisabled:s.promoDisabled?'':'כן'}));tell('מצב המבצע עודכן')}}>השבת / הפעל</Button><Button onClick={()=>formModal('עריכת מבצע',[{label:'שם מבצע',key:'name',value:settings.promo||'הנחת ספטמבר – בלון 48 ק״ג'}],v=>{setSettings(s=>({...s,promo:v.name}));setModal(null);tell('המבצע עודכן')})}>ערוך</Button></>:<><Table headers={['הגדרה','ערך','פעולה']} rows={(active==='מלאי מינימום'?products.map(p=>[p.name,String(p.minimum)]):active==='מחירונים'?D.priceLists.map(pl=>[pl.name,`${products.length} מוצרים · ${Math.round(pl.factor*100)}% ממחיר בסיס`]):active==='נהגים'?drivers.map(d=>[d.name,d.area]):active==='ספקים'?D.suppliers.map(s=>[s.name,s.contact]):active==='אזורי חלוקה'?D.areas.map(a=>[a,'פעיל']):active==='מוצרים'?products.map(p=>[p.name,p.sku]):active==='יעדים'?drivers.map(d=>[d.name,String(goals[d.id]||200)]):active==='התראות'?['קריטי','מלאי נמוך','נהג לא הגיב'].map(n=>[n,'פעיל']):['מנהל','משרד','נהג','טכנאי','מחסן'].map(r=>[r,'פעיל'])).map(([name,value])=>[name,settings[active+name]||value,<Button onClick={()=>formModal('עריכת '+name,[{label:'ערך',key:'value',value:settings[active+name]||value}],v=>{setSettings(s=>({...s,[active+name]:v.value}));setModal(null);log('הגדרות','עדכון '+active,name,value,v.value);tell('ההגדרה עודכנה')})}>ערוך</Button>])}/><Button onClick={()=>demoAction('הוסף '+active)}>הוסף</Button></>}<div className="actions"><Button primary onClick={()=>{log('הגדרות','שמירת '+active,'עסק');tell('ההגדרות נשמרו בהדגמה')}}>שמור</Button></div></Card><Card title="עבודה ללא קליטה – אפשרות עתידית"><Badge>לא הוגדר</Badge><p>היכולת מוצעת לאפיון ואינה ממומשת בדמו.</p></Card>{notes.length>0&&<Card title="רשומות שנוספו בהדגמה">{notes.map((n,i)=><p key={i}>{n}</p>)}</Card>}</>}
 function mapPage(){return <div className="map-layout"><Card title="נהגים במסלול"><p>מפה סכמטית · מיקומים פיקטיביים</p>{drivers.slice(0,3).map((d,i)=><button className="driver-mini" key={d.id} onClick={()=>open('drivers',d.id)}><span className="avatar">{d.name[0]}</span><span><b>{d.name}</b><small>{[8,6,7][i]} עצירות · {d.area}</small></span><Badge>בחלוקה</Badge></button>)}<Button onClick={()=>setModal({title:'ניווט בהדגמה',body:<p>הכתובות פיקטיביות. במערכת העתידית כפתורי Waze ו־Google Maps יפתחו ניווט לכתובת האספקה.</p>})}>פתח ב־Waze / Google Maps</Button></Card><div className="mock-map"><svg viewBox="0 0 800 650" preserveAspectRatio="none"><path d="M0 170 Q220 360 800 110 M0 520 Q390 340 800 550 M180 0 Q490 260 250 650 M620 0 Q440 350 780 650" fill="none" stroke="#fff" strokeWidth="20"/><path d="M125 420 Q230 320 340 280 T590 150" fill="none" stroke="#2a8d7d" strokeWidth="5" strokeDasharray="10 8"/></svg><span className="map-water"/><span className="map-label coast">הים התיכון</span>{D.areas.map((a,i)=><button key={a} className="map-pin" style={{top:(13+i*9%73)+'%',right:(12+i*17%72)+'%'}} onClick={()=>open('orders',orders[i].id)}><Icon name={i<3?'Truck':'MapPin'} size={20}/><b>{a}</b><small>{i<3?drivers[i].name.split(' ')[0]:'נקודת אספקה'}</small></button>)}<div className="map-caption"><span className="dot"/> מפת חלוקה להמחשה · 8 נהגים · 37 הזמנות</div></div></div>}
