 const customer=customers.find(c=>c.id===id);const driver=drivers.find(d=>d.id===id);const vehicle=D.vehicles.find(v=>v.id===id);const technician=D.technicians.find(t=>t.id===id);const supplier=D.suppliers.find(s=>s.id===id);const product=products.find(p=>p.id===id);const serviceProvider=serviceProviders.find(sp=>sp.id===id);
